using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;namespace OperationsRequests.Tests;public class SqlServerConcurrencyTests{static readonly string Cs=Environment.GetEnvironmentVariable("TEST_SQL_CONNECTION")??throw new InvalidOperationException("TEST_SQL_CONNECTION is required.");static DbContextOptions<ApplicationDbContext> Opt()=>new DbContextOptionsBuilder<ApplicationDbContext>().UseSqlServer(Cs).Options;static async Task Seed(){await using var db=new ApplicationDbContext(Opt());await db.Database.EnsureDeletedAsync();await db.Database.EnsureCreatedAsync();var u=new ApplicationUser{Id="staff",UserName="staff",DisplayName="Staff",Email="staff@test"};var r=new TrainingRequest{RequestNumber="TEST-001",Title="test",Description="test",Type=RequestType.Training,Priority=RequestPriority.Medium,RequestedById="staff",Site=new Site{Code="T1",Name="Site",Territory=new Territory{Name="Territory",Country=new Country{Name="Country",Code="TC",Platform=new Platform{Name="Platform"}}}}};db.Add(u);db.Add(r);await db.SaveChangesAsync();}[Fact]public async Task SqlServer_rowversion_rejects_stale_update(){await Seed();await using var a=new ApplicationDbContext(Opt());await using var b=new ApplicationDbContext(Opt());var one=await a.TrainingRequests.SingleAsync();var two=await b.TrainingRequests.SingleAsync();one.Status=RequestStatus.UnderReview;await a.SaveChangesAsync();two.Status=RequestStatus.Escalated;await Assert.ThrowsAsync<DbUpdateConcurrencyException>(()=>b.SaveChangesAsync());}[Fact]public async Task SqlServer_unique_final_decision_rejects_duplicate(){await Seed();await using var db=new ApplicationDbContext(Opt());var id=(await db.TrainingRequests.SingleAsync()).Id;db.RequestDecisions.AddRange(new RequestDecision{TrainingRequestId=id,DecidedById="staff",Action="Approved"},new RequestDecision{TrainingRequestId=id,DecidedById="staff",Action="Approved"});await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());}}


